259	    /**
260	     * Build a {@code customerCode} formatted {@code '<LAST3>-<NNNN>'} where LAST3 is the
261	     * upper-cased first three letters of {@code lastName} and NNNN is a global 4-digit
262	     * zero-padded sequence equal to one more than the current number of owners.
263	     */
264	    private String generateCustomerCode(String lastName) {
265	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
266	        long sequence = ownerRepository.findAll().size() + 1L;
267	        return String.format("%s-%04d", prefix, sequence);
268	    }
