278	    /**
279	     * Rejects saving {@code owner} when its {@code normalized} telephone is already used by any
280	     * other owner, so no two owners can share a telephone number.
281	     *
282	     * @throws DuplicateTelephoneException if another owner already has the same normalized telephone
283	     */
284	    private void assertTelephoneUnique(Owner owner, String normalized) {
285	        if (normalized == null || normalized.isEmpty()) {
286	            return;
287	        }
288	        for (Owner existing : ownerRepository.findAll()) {
289	            if (!existing.getId().equals(owner.getId())
290	                    && normalized.equals(normalizeTelephone(existing.getTelephone()))) {
291	                throw new DuplicateTelephoneException(normalized);
292	            }
293	        }
294	    }
295	
296	    /**
297	     * Enforces the household rule for a new {@code owner} that shares both {@code lastName} and
298	     * {@code address} (compared case-insensitively with collapsed whitespace) with an existing
299	     * owner. When the request does not acknowledge the shared household via
300	     * {@link Owner#isSharesHousehold()} the creation is rejected; when it does, the new owner and
301	     * every matching existing owner are assigned the same stable {@code householdId}. Only applies
302	     * to new owners; updates to an existing owner are left untouched.
303	     *
304	     * @throws DuplicateHouseholdException if another owner already lives at the same household and
305	     *                                     the request does not acknowledge the shared household
306	     */
307	    private void assertHouseholdAllowed(Owner owner) {
308	        if (!owner.isNew()) {
309	            return;
310	        }
311	        String lastName = normalizeHouseholdValue(owner.getLastName());
312	        String address = normalizeHouseholdValue(owner.getAddress());
313	        if (lastName.isEmpty() || address.isEmpty()) {
314	            return;
315	        }
316	        List<Owner> household = new ArrayList<>();
317	        for (Owner existing : ownerRepository.findAll()) {
318	            if (!existing.getId().equals(owner.getId())
319	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))
320	                    && address.equals(normalizeHouseholdValue(existing.getAddress()))) {
321	                household.add(existing);
322	            }
323	        }
324	        if (household.isEmpty()) {
325	            return;
326	        }
327	        if (!owner.isSharesHousehold()) {
328	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
329	        }
330	        String householdId = resolveHouseholdId(lastName, address, household);
331	        owner.setHouseholdId(householdId);
332	        for (Owner existing : household) {
333	            if (existing.getHouseholdId() == null || existing.getHouseholdId().isBlank()) {
334	                existing.setHouseholdId(householdId);
335	                ownerRepository.save(existing);
336	            }
337	        }
338	    }
339	
340	    /**
341	     * Returns the {@code householdId} shared by a household: the first non-blank identifier already
342	     * carried by an existing member, or otherwise a freshly derived stable identifier for the
343	     * household's normalized {@code lastName} and {@code address}.
344	     */
345	    private String resolveHouseholdId(String lastName, String address, List<Owner> household) {
346	        for (Owner existing : household) {
347	            if (existing.getHouseholdId() != null && !existing.getHouseholdId().isBlank()) {
348	                return existing.getHouseholdId();
349	            }
350	        }
351	        return generateHouseholdId(lastName, address);
352	    }
353	
354	    /**
355	     * Derives a stable {@code householdId} formatted {@code 'HH-<12 upper-hex>'} from the SHA-256
356	     * digest of the normalized {@code lastName} and {@code address}, so all owners in the same
357	     * household deterministically share the same identifier.
358	     */
359	    private static String generateHouseholdId(String lastName, String address) {
360	        try {
361	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
362	            byte[] hash = digest.digest((lastName + "\u0000" + address).getBytes(StandardCharsets.UTF_8));
363	            StringBuilder sb = new StringBuilder();
364	            for (int i = 0; i < 6; i++) {
365	                sb.append(String.format("%02X", hash[i]));
366	            }
367	            return "HH-" + sb;
368	        } catch (NoSuchAlgorithmException e) {
369	            throw new IllegalStateException("SHA-256 not available", e);
370	        }
371	    }
372	
373	    /**
374	     * Normalizes a household comparison value by trimming, collapsing runs of whitespace into a
375	     * single space and lower-casing, so comparisons ignore case and incidental whitespace.
376	     */
377	    private static String normalizeHouseholdValue(String value) {
378	        if (value == null) {
379	            return "";
380	        }
381	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
382	    }
