402	    private <T> T findEntityById(Supplier<T> supplier) {
403	        try {
404	            return supplier.get();
405	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
406	            // Just ignore not found exceptions for Jdbc/Jpa realization
407	            return null;
408	        }
409	    }
